#!/usr/bin/env bash
set -euo pipefail
APP_ROOT="${APP:-/app}"
WORK="$(mktemp -d "${TMPDIR:-/tmp}/bench10-oracle.XXXXXX")"
trap 'rm -rf -- "$WORK"' EXIT
python3 - "$WORK" <<'PY_BUNDLE'
import base64, json, pathlib, stat, sys, zlib
root=pathlib.Path(sys.argv[1]); payload=json.loads(zlib.decompress(base64.b64decode('')).decode())
for rel, item in payload.items():
    data=base64.b64decode(item['data']); p=root/rel; p.parent.mkdir(parents=True,exist_ok=True); p.write_bytes(data); p.chmod(item['mode'])
(root/'solve.sh').write_bytes(base64.b64decode('')); (root/'solve.sh').chmod(0o755)
PY_BUNDLE
APP="$APP_ROOT" SOLUTION="$WORK" bash "$WORK/solve.sh"
